  async function applyFaqs(){const container=document.getElementById("support-faq-list");if(!container||typeof supabaseClient==="undefined")return;try{const {data,error}=await supabaseClient.from("site_faqs").select("question,answer").eq("active",true).order("sort_order",{ascending:true}).order("created_at",{ascending:true});if(error||!data?.length)return;const escape=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));container.innerHTML=data.map(row=>`<div class="acc-item"><button class="acc-head">${escape(row.question)} <span class="plus"></span></button><div class="acc-body"><div class="acc-body-inner">${escape(row.answer).replace(/\n/g,"<br>")}</div></div></div>`).join("");}catch(error){console.warn("FAQ settings unavailable.",error?.message||error);}}
  async function applyGuideCards(){if(typeof supabaseClient==="undefined")return;try{const {data,error}=await supabaseClient.from("journal_articles").select("slug,title,summary,collection").eq("active",true).order("sort_order",{ascending:true});if(error||!data?.length)return;for(const guide of data){document.querySelectorAll('a[href^="/journal/"]').forEach(link=>{if(link.getAttribute("href")!==`/journal/${guide.slug}/`)return;const card=link.closest(".journal-card");if(!card)return;const heading=card.querySelector("h2"),summary=card.querySelector("h2 + p");if(heading)heading.textContent=guide.title;if(summary)summary.textContent=guide.summary;});}}catch(error){console.warn("Journal card settings unavailable.",error?.message||error);}}

  window.LZ_SETTINGS_READY=(async()=>{let settings=defaults;if(typeof supabaseClient!=="undefined"){try{const {data,error}=await supabaseClient.from("site_settings").select("value").eq("key","main").maybeSingle();if(error)throw error;settings={...defaults,...(data?.value||{})};}catch(error){console.warn("Site settings unavailable; using built-in defaults.",error?.message||error);}}applySettings(settings);await Promise.allSettled([applyFaqs(),applyGuideCards()]);window.dispatchEvent(new CustomEvent("lz:site-settings-ready",{detail:settings}));return settings;})();
